# owner: platform
"""Plain-text absence notices for parents."""

from rosterkit.errors import ProjectError

def _absent_days(student, marks):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(f"mark for {mark.student_id} given for {student.student_id}")
    return sorted(mark.day for mark in marks if mark.status == "absent")

# ---
def absence_notice(student, marks):
    """Notice naming the student, days missed and the dates in order."""
    days = _absent_days(student, marks)
    if not days:
        raise ProjectError(f"no absences for {student.student_id}")
    dates = ", ".join(item.isoformat() for item in days)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} was absent for {len(days)} day(s): {dates}."
